import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import './Resources.css';

const ResourcesPage = () => {
  // --- SCROLL ANIMATION LOGIC ---
  useEffect(() => {
    const observerOptions = {
      threshold: 0.1, // Trigger when 10% of the element is visible
      rootMargin: "0px 0px -50px 0px" // Offset slightly so it triggers before bottom
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
        }
      });
    }, observerOptions);

    // Select all elements we want to animate
    const revealElements = document.querySelectorAll('.reveal-on-scroll');
    revealElements.forEach(el => observer.observe(el));

    return () => observer.disconnect();
  }, []); // Run once on mount

  // --- DATA ---
  const publications = [
    {
      type: 'Conference Paper',
      title: 'Comparative Analysis of RNN models for Air Pollution Forecasting',
      venue: 'ICICDS-2025',
      status: 'Published'
    },
    {
      type: 'Research Paper',
      title: 'A Comparative Analysis of Conventional Methods for Sensor-Driven Spatial Interpolation',
      venue: 'Eng. Tech & Applied Science Research',
      status: 'Communicated'
    },
    {
      type: 'Conference Paper',
      title: 'AI-Based Environmental Pollution Monitoring with Personalized Health Risk Assessment',
      venue: 'ICSSAI-2025 (Kolkata)',
      status: 'Accepted'
    }
  ];

  const patent = {
    title: 'Artificial Intelligence Integrated Water Level Monitoring Solution with Flood Alerts',
    appNumber: '202441079490',
    filingDate: 'October 25, 2024',
    status: 'Filed with INDIA Patent Office'
  };

  const trainingEvents = [
    { title: 'IoT Impression – Arduino & Raspberry pi', type: 'Hands-on-Workshop', duration: '1 Day', date: 'March 19, 2025', participants: 40 },
    { title: 'Electronic Prototyping & IoT Solutions', type: 'Summer Internship', duration: '15 Days', date: 'June 2-24, 2025', participants: '49 (9 Teams)' },
    { title: 'IoT Powered Robotics: ESP8266 to RPi', type: 'Workshop', duration: '3 Days', date: 'June 25-27, 2025', participants: 37 },
    { title: 'IoT Prototyping and PCB Design', type: 'Value Added Course', duration: '4 Days', date: 'July 1-4, 2025', participants: 63 },
    { title: 'Edge Hardware Design – PCB Workshop', type: 'Workshop', duration: '10 Days', date: 'July 7-17, 2025', participants: 84 },
    { title: 'Embedded System and Digital Design', type: 'Value Added Course', duration: '5 Days', date: 'July 16-21, 2025', participants: 51 },
    { title: 'Raspberry Pi Workshop', type: 'Hands-on-Workshop', duration: '1 Day', date: 'Sept 11, 2025', participants: 63 }
  ];

  const objectives = [
    "Develop intelligent sensor modules for pollution monitoring.",
    "Validate smart water level monitoring with flood alerts.",
    "Create digital systems for water level distribution.",
    "Build a startup & skill development ecosystem.",
    "Develop Explainable AI (XAI) analysis software for IoT."
  ];

  // --- Brochure Logic ---
  const [brochures, setBrochures] = useState([]);
  const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://127.0.0.1:8000';

  useEffect(() => {
    const fetchBrochures = async () => {
      try {
        const response = await fetch(`${API_BASE_URL}/api/brochures/`);
        const data = await response.json();
        const brochureArray = data.results || data;
        if (brochureArray?.length > 0) {
          setBrochures(brochureArray.map(b => ({
            title: b.title,
            description: b.description,
            url: b.file.startsWith('http') ? b.file : `${API_BASE_URL}${b.file}`,
            category: b.category || 'Document'
          })));
        }
      } catch (error) { console.error(error); }
    };
    fetchBrochures();
  }, [API_BASE_URL]);

  return (
    <div className="resources-page-container">
      
      {/* 1. Header */}
      <nav className="aiiot-header-local">
        <div className="nav-container-inner">
           <Link to="/" style={{ textDecoration: 'none' }}>
             <span className="logo-text">AI-IoT Innovations</span>
           </Link>
           <div className="desktop-nav" style={{ display: 'flex', alignItems: 'center' }}>
             <a href="https://aiiot.it.com/project/intelligent-sensor" className="nav-link">Solutions</a>
             <Link to="/resources" className="nav-link active">Resources</Link>
             <Link to="/contact" className="nav-cta">Get in Touch</Link>
           </div>
        </div>
      </nav>

      <div className="resources-content-wrapper">
        
        {/* 2. Hero Section */}
        <section className="resources-hero-section reveal-on-scroll">
          <span className="eyebrow">Center for Excellence</span>
          <h1 className="page-title">Research, Development <br/>& Innovation.</h1>
          <p className="page-intro">
            Advancing preventive environmental monitoring through intelligent sensor networking. 
            We build the future of connected climate solutions.
          </p>

          <div className="objectives-list-clean reveal-on-scroll delay-100">
             {objectives.map((obj, i) => (
                <div key={i} className="objective-item">
                   <span className="obj-number">0{i+1}</span>
                   <span style={{color: '#334155'}}>{obj}</span>
                </div>
             ))}
          </div>
        </section>

        {/* 3. Research & IP */}
        <div className="section-separator reveal-on-scroll"></div>
        
        <section className="reveal-on-scroll">
          <div className="section-header">
            <h2 className="section-title">Intellectual Property & Publications</h2>
            <span style={{color: '#64748b'}}>2024-2025</span>
          </div>
          
          <div className="grid-layout">
             {/* Patent */}
             <div className="minimal-card patent-style reveal-on-scroll delay-100">
                <span className="card-tag tag-filed">Patent Filed</span>
                <h3 className="card-h3">{patent.title}</h3>
                <div className="card-meta">
                   App No: {patent.appNumber}<br/>
                   Filed: {patent.filingDate}
                </div>
                <div className="card-footer-line">
                   Status: {patent.status}
                </div>
             </div>

             {/* Papers */}
             {publications.map((pub, idx) => (
                <div key={idx} className={`minimal-card reveal-on-scroll delay-${(idx+2) * 100}`}>
                   <span className={`card-tag ${pub.status === 'Published' || pub.status === 'Accepted' ? 'tag-accepted' : 'tag-published'}`}>
                     {pub.status}
                   </span>
                   <h3 className="card-h3">{pub.title}</h3>
                   <div className="card-meta">Venue: {pub.venue}</div>
                   <div className="card-footer-line">{pub.type}</div>
                </div>
             ))}
          </div>
        </section>

        {/* 4. Training */}
        <div className="section-separator reveal-on-scroll"></div>

        <section className="reveal-on-scroll">
           <div className="section-header">
             <h2 className="section-title">Workshops & Manpower</h2>
             <span style={{color: '#64748b'}}>Training Statistics</span>
           </div>
           
           <div className="clean-table-wrapper reveal-on-scroll delay-100">
              <table className="clean-table">
                 <thead>
                    <tr>
                       <th>Program Title</th>
                       <th>Type</th>
                       <th>Duration</th>
                       <th>Date</th>
                       <th>Participants</th>
                    </tr>
                 </thead>
                 <tbody>
                    {trainingEvents.map((ev, i) => (
                       <tr key={i}>
                          <td style={{fontWeight: 600}}>{ev.title}</td>
                          <td>{ev.type}</td>
                          <td>{ev.duration}</td>
                          <td>{ev.date}</td>
                          <td>{ev.participants}</td>
                       </tr>
                    ))}
                 </tbody>
              </table>
           </div>
        </section>

        {/* 5. Downloads */}
        <div className="section-separator reveal-on-scroll"></div>

        <section className="reveal-on-scroll">
           <div className="section-header">
             <h2 className="section-title">Downloads</h2>
           </div>
           
           <div className="brochure-list">
             {brochures.length === 0 ? <p style={{color:'#94a3b8'}}>Loading...</p> : brochures.map((b, i) => (
                <div key={i} className="brochure-item reveal-on-scroll delay-100">
                   <div>
                      <h4 style={{margin: '0 0 0.5rem 0', fontSize: '1.1rem'}}>{b.title}</h4>
                      <p style={{margin: 0, color: '#64748b', fontSize: '0.9rem'}}>{b.description}</p>
                   </div>
                   <a href={b.url} target="_blank" rel="noopener noreferrer" className="download-link">
                      Download PDF <span>↓</span>
                   </a>
                </div>
             ))}
           </div>
        </section>

        <div style={{marginTop: '6rem', textAlign: 'center'}} className="reveal-on-scroll">
           <Link to="/" style={{color: '#94a3b8', textDecoration: 'none'}}>Back to Home</Link>
        </div>

      </div>
    </div>
  );
};

export default ResourcesPage;
